// Memory R/W abstraction for 32-bit x86 target process
bool write_process_memory(uint32_t pid, uint64_t address, const void* data, size_t size) {
#if defined(_WIN32)
    HANDLE hProcess = OpenProcess(PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!hProcess) return false;
    DWORD old_protect = 0;
    VirtualProtectEx(hProcess, reinterpret_cast<LPVOID>(address), size, PAGE_EXECUTE_READWRITE, &old_protect);
    SIZE_T written = 0;
    BOOL ok = WriteProcessMemory(hProcess, reinterpret_cast<LPVOID>(address), data, size, &written);
    VirtualProtectEx(hProcess, reinterpret_cast<LPVOID>(address), size, old_protect, &old_protect);
    CloseHandle(hProcess);
    return ok && (written == size);
#elif defined(__APPLE__)
    mach_port_t task = MACH_PORT_NULL;
    if (task_for_pid(mach_task_self(), pid, &task) != KERN_SUCCESS) return false;
    kern_return_t kr = mach_vm_write(task, address, reinterpret_cast<vm_offset_t>(data), static_cast<mach_msg_type_number_t>(size));
    return kr == KERN_SUCCESS;
#elif defined(__linux__)
    struct iovec local{ const_cast<void*>(data), size };
    struct iovec remote{ reinterpret_cast<void*>(address), size };
    ssize_t written = process_vm_writev(pid, &local, 1, &remote, 1, 0);
    return written == static_cast<ssize_t>(size);
#else
    (void)pid; (void)address; (void)data; (void)size;
    return false;
#endif
}

bool read_process_memory(uint32_t pid, uint64_t address, void* buffer, size_t size) {
#if defined(_WIN32)
    HANDLE hProcess = OpenProcess(PROCESS_VM_READ, FALSE, pid);
    if (!hProcess) return false;
    SIZE_T read_bytes = 0;
    BOOL ok = ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(address), buffer, size, &read_bytes);
    CloseHandle(hProcess);
    return ok && (read_bytes == size);
#elif defined(__APPLE__)
    mach_port_t task = MACH_PORT_NULL;
    if (task_for_pid(mach_task_self(), pid, &task) != KERN_SUCCESS) return false;
    mach_vm_size_t out_size = 0;
    kern_return_t kr = mach_vm_read_overwrite(task, address, size, reinterpret_cast<mach_vm_address_t>(buffer), &out_size);
    return kr == KERN_SUCCESS && (out_size == size);
#elif defined(__linux__)
    struct iovec local{ buffer, size };
    struct iovec remote{ reinterpret_cast<void*>(address), size };
    ssize_t read_bytes = process_vm_readv(pid, &local, 1, &remote, 1, 0);
    return read_bytes == static_cast<ssize_t>(size);
#else
    (void)pid; (void)address; (void)buffer; (void)size;
    return false;
#endif
}

uint32_t find_process_by_name(const std::string& process_name) {
#if defined(_WIN32)
    HANDLE snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snapshot == INVALID_HANDLE_VALUE) return 0;

    PROCESSENTRY32 entry;
    entry.dwSize = sizeof(PROCESSENTRY32);

    if (Process32First(snapshot, &entry)) {
        do {
            if (_stricmp(entry.szExeFile, process_name.c_str()) == 0) {
                CloseHandle(snapshot);
                return entry.th32ProcessID;
            }
        } while (Process32Next(snapshot, &entry));
    }
    CloseHandle(snapshot);
#elif defined(__APPLE__)
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "pgrep -i -f '%s' | tail -n 1", process_name.c_str());
    FILE* fp = popen(cmd, "r");
    if (fp) {
        char buf[64];
        if (fgets(buf, sizeof(buf), fp)) {
            pclose(fp);
            return static_cast<uint32_t>(std::stoul(buf));
        }
        pclose(fp);
    }
#endif
    (void)process_name;
    return 0;
}

